-- Lifeforms schema + effects. Existing production signature is preserved.
CREATE TABLE IF NOT EXISTS public.lifeform_definitions(id text PRIMARY KEY,name text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',discovered_by_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.lifeform_definitions(id,name,description,discovered_by_default) VALUES('HUMAN','Humans','Civilización equilibrada.',true),('ROCKTAL','Rock''tal','Civilización mineral.',false),('MECHA','Mecha','Civilización mecánica.',false),('KALESH','Kaelesh','Civilización psiónica.',false) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,discovered_by_default=EXCLUDED.discovered_by_default;
CREATE TABLE IF NOT EXISTS public.planet_lifeforms(planet_id uuid PRIMARY KEY REFERENCES public.planets(id) ON DELETE CASCADE,lifeform_id text NOT NULL REFERENCES public.lifeform_definitions(id),active boolean NOT NULL DEFAULT true,population_t1 numeric NOT NULL DEFAULT 1000 CHECK(population_t1>=0),population_t2 numeric NOT NULL DEFAULT 0 CHECK(population_t2>=0),population_t3 numeric NOT NULL DEFAULT 0 CHECK(population_t3>=0),food numeric NOT NULL DEFAULT 1000 CHECK(food>=0),experience numeric NOT NULL DEFAULT 0 CHECK(experience>=0),lifeform_level integer NOT NULL DEFAULT 0 CHECK(lifeform_level BETWEEN 0 AND 100),discovered_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.player_lifeform_discoveries(player_id uuid NOT NULL REFERENCES public.players(id) ON DELETE CASCADE,lifeform_id text NOT NULL REFERENCES public.lifeform_definitions(id),discovered boolean NOT NULL DEFAULT true,experience numeric NOT NULL DEFAULT 0 CHECK(experience>=0),level integer NOT NULL DEFAULT 0 CHECK(level BETWEEN 0 AND 100),discovered_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(player_id,lifeform_id));
CREATE TABLE IF NOT EXISTS public.lifeform_building_definitions(id text PRIMARY KEY,lifeform_id text NOT NULL REFERENCES public.lifeform_definitions(id),slot integer NOT NULL CHECK(slot BETWEEN 1 AND 12),name text NOT NULL,description text NOT NULL DEFAULT '',base_metal numeric NOT NULL DEFAULT 1000,base_crystal numeric NOT NULL DEFAULT 1000,base_deuterium numeric NOT NULL DEFAULT 0,cost_factor numeric NOT NULL DEFAULT 1.5,base_build_time_seconds integer NOT NULL DEFAULT 60,time_factor numeric NOT NULL DEFAULT 1.5,effect_key text,effect_value numeric NOT NULL DEFAULT 0,max_level integer NOT NULL DEFAULT 100,UNIQUE(lifeform_id,slot));
CREATE TABLE IF NOT EXISTS public.planet_lifeform_buildings(planet_id uuid NOT NULL REFERENCES public.planets(id) ON DELETE CASCADE,building_id text NOT NULL REFERENCES public.lifeform_building_definitions(id),level integer NOT NULL DEFAULT 0 CHECK(level>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(planet_id,building_id));
CREATE TABLE IF NOT EXISTS public.lifeform_building_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),planet_id uuid NOT NULL REFERENCES public.planets(id) ON DELETE CASCADE,building_id text NOT NULL REFERENCES public.lifeform_building_definitions(id),target_level integer NOT NULL CHECK(target_level>=1),started_at timestamptz NOT NULL DEFAULT now(),finishes_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'COMPLETED' CHECK(status IN ('QUEUED','COMPLETED','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.lifeform_research_definitions(id text PRIMARY KEY,lifeform_id text NOT NULL REFERENCES public.lifeform_definitions(id),slot integer NOT NULL CHECK(slot BETWEEN 1 AND 18),tier integer NOT NULL CHECK(tier BETWEEN 1 AND 3),name text NOT NULL,description text NOT NULL DEFAULT '',base_metal numeric NOT NULL DEFAULT 10000,base_crystal numeric NOT NULL DEFAULT 10000,base_deuterium numeric NOT NULL DEFAULT 5000,cost_factor numeric NOT NULL DEFAULT 1.5,base_research_time_seconds integer NOT NULL DEFAULT 60,time_factor numeric NOT NULL DEFAULT 1.5,effect_key text,effect_value numeric NOT NULL DEFAULT 0,max_level integer NOT NULL DEFAULT 100,UNIQUE(lifeform_id,slot));
CREATE TABLE IF NOT EXISTS public.planet_lifeform_research(planet_id uuid NOT NULL REFERENCES public.planets(id) ON DELETE CASCADE,slot integer NOT NULL CHECK(slot BETWEEN 1 AND 18),research_id text NOT NULL REFERENCES public.lifeform_research_definitions(id),level integer NOT NULL DEFAULT 0 CHECK(level>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(planet_id,slot),UNIQUE(planet_id,research_id));
CREATE TABLE IF NOT EXISTS public.lifeform_research_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),planet_id uuid NOT NULL REFERENCES public.planets(id) ON DELETE CASCADE,research_id text NOT NULL REFERENCES public.lifeform_research_definitions(id),target_level integer NOT NULL CHECK(target_level>=1),started_at timestamptz NOT NULL DEFAULT now(),finishes_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'COMPLETED' CHECK(status IN ('QUEUED','COMPLETED','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.player_lifeform_discoveries(player_id,lifeform_id) SELECT p.id,'HUMAN' FROM public.players p ON CONFLICT(player_id,lifeform_id) DO NOTHING;
INSERT INTO public.planet_lifeforms(planet_id,lifeform_id) SELECT p.id,'HUMAN' FROM public.planets p ON CONFLICT(planet_id) DO NOTHING;

