INSERT INTO public.lifeform_research_definitions(id,lifeform_id,slot,tier,name,description,effect_key,effect_value,base_metal,base_crystal,base_deuterium,cost_factor,base_research_time_seconds,time_factor)
SELECT id,lf,slot,CASE WHEN slot<=6 THEN 1 WHEN slot<=12 THEN 2 ELSE 3 END,name,'Lifeform research',effect_key,effect_value,10000*power(1.35,slot-1),7000*power(1.35,slot-1),4000*power(1.35,slot-1),1.5,120,1.5 FROM r ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,effect_key=EXCLUDED.effect_key,effect_value=EXCLUDED.effect_value,tier=EXCLUDED.tier;
CREATE INDEX IF NOT EXISTS idx_planet_lifeforms_active ON public.planet_lifeforms(planet_id) WHERE active=true;
CREATE INDEX IF NOT EXISTS idx_lifeform_research_effect ON public.planet_lifeform_research(research_id,planet_id);
CREATE INDEX IF NOT EXISTS idx_lifeform_buildings_planet ON public.planet_lifeform_buildings(planet_id);
CREATE OR REPLACE FUNCTION public.lifeform_experience_multiplier(p_level integer) RETURNS numeric LANGUAGE sql IMMUTABLE AS $function$ SELECT 1+least(greatest(COALESCE(p_level,0),0),100)/1000.0; $function$;
CREATE OR REPLACE FUNCTION public.get_active_lifeform_research_effect(p_player_id uuid,p_effect_key text) RETURNS numeric LANGUAGE sql STABLE AS $function$ SELECT COALESCE(SUM(plr.level*lrd.effect_value*public.lifeform_experience_multiplier(pl.lifeform_level)),0) FROM public.planets p JOIN public.planet_lifeforms pl ON pl.planet_id=p.id AND pl.active=true JOIN public.planet_lifeform_research plr ON plr.planet_id=p.id JOIN public.lifeform_research_definitions lrd ON lrd.id=plr.research_id WHERE p.player_id=p_player_id AND lrd.effect_key=p_effect_key; $function$;
CREATE OR REPLACE FUNCTION public.get_planet_lifeform_building_effect(p_planet_id uuid,p_effect_key text) RETURNS numeric LANGUAGE sql STABLE AS $function$ SELECT COALESCE(SUM(plb.level*lbd.effect_value),0) FROM public.planet_lifeform_buildings plb JOIN public.lifeform_building_definitions lbd ON lbd.id=plb.building_id WHERE plb.planet_id=p_planet_id AND lbd.effect_key=p_effect_key; $function$;
CREATE OR REPLACE FUNCTION public.calculate_lifeform_building_time(p_planet_id uuid,p_building_id text,p_target_level integer) RETURNS numeric LANGUAGE plpgsql STABLE AS $function$ DECLARE v_u uuid;v_rate numeric;v_evolution numeric;v_def public.lifeform_building_definitions%ROWTYPE;v_bonus numeric; BEGIN SELECT universe_id INTO v_u FROM public.planets WHERE id=p_planet_id;IF v_u IS NULL THEN RAISE EXCEPTION 'Planet % does not exist',p_planet_id;END IF;SELECT * INTO v_def FROM public.lifeform_building_definitions WHERE id=p_building_id;IF NOT FOUND THEN RAISE EXCEPTION 'Building % does not exist',p_building_id;END IF;SELECT lifeform_speed INTO v_rate FROM public.universes WHERE id=v_u;v_evolution:=public.calculate_universe_evolution_rate(v_u);v_bonus:=public.get_planet_lifeform_building_effect(p_planet_id,'building_speed_percent');RETURN round((v_def.base_build_time_seconds*power(v_def.time_factor,p_target_level-1))/(v_rate*sqrt(v_evolution)*(1+v_bonus/100)),4);END;$function$;
CREATE OR REPLACE FUNCTION public.start_lifeform_building(p_planet_id uuid,p_building_id text) RETURNS jsonb LANGUAGE plpgsql AS $function$ DECLARE v_def public.lifeform_building_definitions%ROWTYPE;v_lf text;v_level integer;v_target integer;v_id uuid; BEGIN SELECT * INTO v_def FROM public.lifeform_building_definitions WHERE id=p_building_id;IF NOT FOUND THEN RAISE EXCEPTION 'Unknown lifeform building %',p_building_id;END IF;SELECT lifeform_id INTO v_lf FROM public.planet_lifeforms WHERE planet_id=p_planet_id AND active=true;IF v_lf IS NULL OR v_lf<>v_def.lifeform_id THEN RAISE EXCEPTION 'Active lifeform does not match building';END IF;SELECT COALESCE(level,0) INTO v_level FROM public.planet_lifeform_buildings WHERE planet_id=p_planet_id AND building_id=p_building_id;v_target:=v_level+1;IF v_target>v_def.max_level THEN RAISE EXCEPTION 'Max level reached';END IF;INSERT INTO public.planet_lifeform_buildings(planet_id,building_id,level) VALUES(p_planet_id,p_building_id,v_target) ON CONFLICT(planet_id,building_id) DO UPDATE SET level=EXCLUDED.level,updated_at=now();INSERT INTO public.lifeform_building_queue(planet_id,building_id,target_level,started_at,finishes_at,status) VALUES(p_planet_id,p_building_id,v_target,now(),now(),'COMPLETED') RETURNING id INTO v_id;RETURN jsonb_build_object('queue_id',v_id,'building_id',p_building_id,'level',v_target,'completed',true,'accelerated',true);END;$function$;
CREATE OR REPLACE FUNCTION public.calculate_lifeform_research_time(p_planet_id uuid,p_research_id text,p_target_level integer) RETURNS numeric LANGUAGE plpgsql STABLE AS $function$ DECLARE v_u uuid;v_player uuid;v_rate numeric;v_evolution numeric;v_def public.lifeform_research_definitions%ROWTYPE;v_bonus numeric; BEGIN SELECT universe_id,player_id INTO v_u,v_player FROM public.planets WHERE id=p_planet_id;IF v_u IS NULL THEN RAISE EXCEPTION 'Planet % does not exist',p_planet_id;END IF;SELECT * INTO v_def FROM public.lifeform_research_definitions WHERE id=p_research_id;IF NOT FOUND THEN RAISE EXCEPTION 'Research % does not exist',p_research_id;END IF;SELECT lifeform_speed INTO v_rate FROM public.universes WHERE id=v_u;v_evolution:=public.calculate_universe_evolution_rate(v_u);v_bonus:=public.get_active_lifeform_research_effect(v_player,'research_speed_percent');RETURN round((v_def.base_research_time_seconds*power(v_def.time_factor,p_target_level-1))/(v_rate*sqrt(v_evolution)*(1+v_bonus/100)),4);END;$function$;
CREATE OR REPLACE FUNCTION public.start_lifeform_research(p_planet_id uuid,p_research_id text) RETURNS jsonb LANGUAGE plpgsql AS $function$ DECLARE v_def public.lifeform_research_definitions%ROWTYPE;v_active text;v_level integer;v_target integer;v_id uuid;BEGIN SELECT * INTO v_def FROM public.lifeform_research_definitions WHERE id=p_research_id;IF NOT FOUND THEN RAISE EXCEPTION 'Unknown lifeform research %',p_research_id;END IF;SELECT lifeform_id INTO v_active FROM public.planet_lifeforms WHERE planet_id=p_planet_id AND active=true;IF v_active IS NULL THEN RAISE EXCEPTION 'No active lifeform';END IF;SELECT level INTO v_level FROM public.planet_lifeform_research WHERE planet_id=p_planet_id AND slot=v_def.slot;v_level:=COALESCE(v_level,0);v_target:=v_level+1;IF v_target>v_def.max_level THEN RAISE EXCEPTION 'Max level reached';END IF;INSERT INTO public.planet_lifeform_research(planet_id,slot,research_id,level) VALUES(p_planet_id,v_def.slot,p_research_id,v_target) ON CONFLICT(planet_id,slot) DO UPDATE SET research_id=EXCLUDED.research_id,level=EXCLUDED.level,updated_at=now();INSERT INTO public.lifeform_research_queue(planet_id,research_id,target_level,started_at,finishes_at,status) VALUES(p_planet_id,p_research_id,v_target,now(),now(),'COMPLETED') RETURNING id INTO v_id;RETURN jsonb_build_object('queue_id',v_id,'research_id',p_research_id,'slot',v_def.slot,'level',v_target,'completed',true,'accelerated',true);END;$function$;
CREATE OR REPLACE FUNCTION public.calculate_planet_production(p_planet_id uuid) RETURNS TABLE(metal_per_hour numeric,crystal_per_hour numeric,deuterium_per_hour numeric,energy_per_hour numeric) LANGUAGE plpgsql AS $function$ DECLARE v_universe_id uuid;v_player_id uuid;v_metal_level integer:=0;v_crystal_level integer:=0;v_deuterium_level integer:=0;v_solar_level integer:=0;v_economy_rate numeric;v_production_rate numeric;v_item_bonus numeric:=0;v_prod_bonus numeric:=0;v_metal_bonus numeric:=0;v_crystal_bonus numeric:=0;v_deut_bonus numeric:=0;v_energy_bonus numeric:=0;BEGIN SELECT p.universe_id,p.player_id INTO v_universe_id,v_player_id FROM public.planets p WHERE p.id=p_planet_id;IF v_universe_id IS NULL THEN RAISE EXCEPTION 'Planet % does not exist',p_planet_id;END IF;SELECT r.economy,r.production INTO v_economy_rate,v_production_rate FROM public.calculate_universe_rates(v_universe_id) r;SELECT COALESCE(MAX(level),0) INTO v_metal_level FROM public.planet_buildings WHERE planet_id=p_planet_id AND building_id='metal_mine';SELECT COALESCE(MAX(level),0) INTO v_crystal_level FROM public.planet_buildings WHERE planet_id=p_planet_id AND building_id='crystal_mine';SELECT COALESCE(MAX(level),0) INTO v_deuterium_level FROM public.planet_buildings WHERE planet_id=p_planet_id AND building_id='deuterium_synthesizer';SELECT COALESCE(MAX(level),0) INTO v_solar_level FROM public.planet_buildings WHERE planet_id=p_planet_id AND building_id='solar_plant';v_item_bonus:=public.get_active_expedition_item_effect(v_player_id,p_planet_id,'production_percent');v_prod_bonus:=public.get_active_lifeform_research_effect(v_player_id,'production_percent');v_metal_bonus:=public.get_active_lifeform_research_effect(v_player_id,'metal_production_percent')+public.get_planet_lifeform_building_effect(p_planet_id,'metal_production_percent');v_crystal_bonus:=public.get_active_lifeform_research_effect(v_player_id,'crystal_production_percent')+public.get_planet_lifeform_building_effect(p_planet_id,'crystal_production_percent');v_deut_bonus:=public.get_active_lifeform_research_effect(v_player_id,'deuterium_production_percent')+public.get_planet_lifeform_building_effect(p_planet_id,'deuterium_production_percent');v_energy_bonus:=public.get_active_lifeform_research_effect(v_player_id,'energy_percent')+public.get_planet_lifeform_building_effect(p_planet_id,'energy_percent');RETURN QUERY SELECT 30*v_metal_level*power(1.1,v_metal_level)*v_economy_rate*v_production_rate*(1+(v_item_bonus+v_prod_bonus+v_metal_bonus)/100),20*v_crystal_level*power(1.1,v_crystal_level)*v_economy_rate*v_production_rate*(1+(v_item_bonus+v_prod_bonus+v_crystal_bonus)/100),10*v_deuterium_level*power(1.1,v_deuterium_level)*v_economy_rate*v_production_rate*(1+(v_item_bonus+v_prod_bonus+v_deut_bonus)/100),20*v_solar_level*power(1.1,v_solar_level)*v_economy_rate*v_production_rate*(1+v_energy_bonus/100);END;$function$;
